/** Resolve a book title ("Cambridge Primary Paths 3", "CPP 2", "Primary Path 1") to "CPP1" | "CPP2" | "CPP3" | null. */
export function resolveCoursebookId(bookTitle) {
  const raw = String(bookTitle || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!raw) return null;
  for (const [id, meta] of Object.entries(CPP_BOOKS)) {
    if (meta.aliases.some((a) => raw === a || raw.includes(a))) return id;
  }
  const m = raw.match(/primary\s*paths?\s*([123])\b/i) || raw.match(/\bcpp\s*([123])\b/i);
  if (m) return `CPP${m[1]}`;
  return null;
}

/**
 * Page spans and section presets for a unit (1..9). Every unit has the same layout:
 * Big Question (2 pages), Section A (8 pages), Section B (to the end of the unit).
 * Unit and reading titles come from the official Scope and Sequence.
 */
export function getCppUnitStructure(bookId, unitNum) {
  const u = Number(unitNum);
  if (!bookId || !CPP_BOOKS[bookId] || !Number.isInteger(u) || u < 1 || u > 9) return null;
  const sbStart = 6 + (u - 1) * 22;
  const sbEnd = sbStart + 21;
  const wbStart = 3 + (u - 1) * 10;
  const wbEnd = wbStart + 9;
  const bigQuestionWords = CPP_WORDBANK
    .filter((e) => e.bookId === bookId && e.unit === u && e.section === "BQ")
    .map((e) => e.english);
  const section = (id, label, from, to, wb) => ({
    id, label: `${label} (p. ${from}–${to})`, shortLabel: label, pageRange: `${from}–${to}`, startPage: from, endPage: to, wbRange: wb,
  });
  return {
    bookId,
    bookTitle: CPP_BOOKS[bookId].title,
    recommendedProfile: CPP_BOOKS[bookId].recommendedProfile,
    cefr: CPP_BOOKS[bookId].cefr,
    unit: u,
    unitTitle: CPP_BOOKS[bookId].units?.[u]?.title || `Unit ${u}`,
    nonfictionTitle: CPP_BOOKS[bookId].units?.[u]?.nonfiction || "",
    fictionTitle: CPP_BOOKS[bookId].units?.[u]?.fiction || "",
    bigQuestionWords,
    sbStart,
    sbEnd,
    wbStart,
    wbEnd,
    sections: [
      section("FULL", `Full Unit ${u}`, sbStart, sbEnd, `WB p. ${wbStart}–${wbEnd}`),
      section("BQ", "Big Question", sbStart, sbStart + 1, `WB p. ${wbStart}`),
      section("A", `${u}A`, sbStart + 2, sbStart + 9, `WB p. ${wbStart}–${wbStart + 4}`),
      section("B", `${u}B`, sbStart + 10, sbEnd, `WB p. ${wbStart + 5}–${wbEnd}`),
    ],
  };
}

/**
 * Parse a flexible page range ("118–120", "118-125", "p. 118, 120", "WB 53-57", "8") into
 * numeric intervals, and detect an explicit "WB" / "Workbook".
 */
export function parsePageRangeSpec(pageRangeStr) {
  const raw = String(pageRangeStr || "").trim();
  if (!raw) return { hasPages: false, intervals: [], explicitWb: false, minPage: null, maxPage: null };
  const explicitWb = /\b(wb|workbook)\b/i.test(raw);
  const cleaned = raw
    .replace(/\b(wb|workbook|sb|student'?s?\s*book|pages?|pp?\.?)\b/gi, " ")
    .replace(/[–—−~]/g, "-");
  const intervals = [];
  for (const part of cleaned.split(/[,;&]+/).map((s) => s.trim()).filter(Boolean)) {
    const rangeMatch = part.match(/(\d+)\s*-\s*(\d+)/);
    if (rangeMatch) {
      const a = Number(rangeMatch[1]);
      const b = Number(rangeMatch[2]);
      intervals.push([Math.min(a, b), Math.max(a, b)]);
      continue;
    }
    const nums = part.match(/\d+/g);
    if (nums && nums.length === 1) intervals.push([Number(nums[0]), Number(nums[0])]);
    else if (nums && nums.length >= 2) {
      const a = Number(nums[0]);
      const b = Number(nums[nums.length - 1]);
      intervals.push([Math.min(a, b), Math.max(a, b)]);
    }
  }
  if (!intervals.length) return { hasPages: false, intervals: [], explicitWb, minPage: null, maxPage: null };
  return {
    hasPages: true,
    intervals,
    explicitWb,
    minPage: Math.min(...intervals.map((i) => i[0])),
    maxPage: Math.max(...intervals.map((i) => i[1])),
  };
}

/** Which unit (1..9) a Student's Book (or "WB …" Workbook) page belongs to. */
export function inferUnitFromPages(bookId, pageRangeStr) {
  if (!bookId || !CPP_BOOKS[bookId]) return null;
  const parsed = parsePageRangeSpec(pageRangeStr);
  if (!parsed.hasPages || parsed.minPage === null) return null;
  const p = parsed.minPage;
  if (parsed.explicitWb) return p >= 3 && p <= 92 ? Math.min(9, Math.max(1, Math.floor((p - 3) / 10) + 1)) : null;
  return p >= 6 && p <= 203 ? Math.min(9, Math.max(1, Math.floor((p - 6) / 22) + 1)) : null;
}

/**
 * Query the official word list.
 * - bookId or bookTitle; unit (1..9, inferred from pageRange when missing)
 * - pageRange: filters Student's Book words to those pages
 * - includeSb / includeWb (default true)
 * - wbScope: "unit" (every Workbook word of the unit) or "section" (Workbook words of the
 *   section(s) the chosen pages belong to)
 */
export function queryCoursebookWords(options = {}) {
  const bookId = options.bookId || resolveCoursebookId(options.bookTitle);
  if (!bookId || !CPP_BOOKS[bookId]) {
    return { supported: false, bookId: null, unit: null, words: [], counts: { sb: 0, wb: 0, total: 0 } };
  }
  const parsedPages = parsePageRangeSpec(options.pageRange);
  let unit = Number(options.unit) || 0;
  if ((!unit || unit < 1 || unit > 9) && parsedPages.hasPages) unit = inferUnitFromPages(bookId, options.pageRange) || 0;
  const includeSb = options.includeSb !== false;
  const includeWb = options.includeWb !== false;
  const wbScope = options.wbScope || "unit";
  const inPages = (p, intervals) => intervals.some(([a, b]) => p >= a && p <= b);

  const unitStruct = unit >= 1 && unit <= 9 ? getCppUnitStructure(bookId, unit) : null;
  let touchesA = true;
  let touchesB = true;
  if (unitStruct && parsedPages.hasPages && !parsedPages.explicitWb) {
    const aEnd = unitStruct.sbStart + 9;
    touchesA = parsedPages.intervals.some(([a, b]) => a <= aEnd && b >= unitStruct.sbStart);
    touchesB = parsedPages.intervals.some(([a, b]) => b >= aEnd + 1 && a <= unitStruct.sbEnd);
  }

  const candidates = CPP_WORDBANK.filter((entry) => {
    if (entry.bookId !== bookId) return false;
    if (unit >= 1 && unit <= 9 && entry.unit !== unit) return false;
    if (entry.source === "sb") {
      if (!includeSb) return false;
      if (parsedPages.hasPages) return !parsedPages.explicitWb && inPages(entry.sbPage, parsedPages.intervals);
      return true;
    }
    if (!includeWb) return false;
    if (parsedPages.hasPages && parsedPages.explicitWb) return inPages(entry.wbPage, parsedPages.intervals);
    if (parsedPages.hasPages && wbScope === "section") {
      if (touchesA && !touchesB) return entry.wbSubSection === "A";
      if (touchesB && !touchesA) return entry.wbSubSection === "B";
    }
    return true;
  });

  // One entry per headword (the official list repeats some words in the Workbook).
  const seen = new Map();
  for (const item of candidates) {
    const key = item.english.toLowerCase().trim();
    if (!seen.has(key)) seen.set(key, { ...item });
  }
  const words = Array.from(seen.values());
  return {
    supported: true,
    bookId,
    bookTitle: CPP_BOOKS[bookId].title,
    recommendedProfile: CPP_BOOKS[bookId].recommendedProfile,
    cefr: CPP_BOOKS[bookId].cefr,
    unit: unit || null,
    hasPageFilter: parsedPages.hasPages,
    unitStructure: unitStruct,
    words,
    counts: {
      sb: words.filter((w) => w.source === "sb").length,
      wb: words.filter((w) => w.source === "wb").length,
      total: words.length,
    },
  };
}

const CONTENT_TYPES = new Set(["n.", "v.", "adj.", "adv.", "phr. v.", "phr."]);

/**
 * Pick up to `maxCount` words for a worksheet: content words first, spread evenly across
 * the unit so the Big Question, Section A and Section B are all represented.
 */
export function selectSmartCoursebookWords(words, maxCount = 0) {
  if (!Array.isArray(words) || !words.length) return [];
  const cap = Number(maxCount) || 0;
  if (cap <= 0 || words.length <= cap) return [...words];
  const scored = words.map((w, idx) => ({
    w,
    idx,
    score: (CONTENT_TYPES.has(w.type) ? 10 : 0) + (w.source === "sb" ? 4 : 0) + (w.english.length >= 5 ? 3 : 0),
  }));
  // Round-robin over the unit's sections so no part of the unit is skipped.
  const bySection = new Map();
  for (const s of [...scored].sort((a, b) => b.score - a.score || a.idx - b.idx)) {
    const key = s.w.source === "wb" ? `WB-${s.w.wbSubSection || ""}` : s.w.section || "";
    if (!bySection.has(key)) bySection.set(key, []);
    bySection.get(key).push(s);
  }
  const queues = [...bySection.values()];
  const picked = [];
  while (picked.length < cap && queues.some((q) => q.length)) {
    for (const q of queues) {
      if (picked.length >= cap) break;
      if (q.length) picked.push(q.shift());
    }
  }
  return picked.sort((a, b) => a.idx - b.idx).map((x) => x.w);
}

/** Look up one English word, preferring the active book and unit. */
export function lookupCoursebookWord(english, bookTitleOrId = "", unitNum = 0) {
  const key = String(english || "").trim().toLowerCase();
  if (!key) return null;
  const bookId = CPP_BOOKS[bookTitleOrId] ? bookTitleOrId : resolveCoursebookId(bookTitleOrId);
  const u = Number(unitNum) || 0;
  const same = (e) => e.english.toLowerCase().trim() === key;
  if (bookId && u >= 1 && u <= 9) {
    const hit = CPP_WORDBANK.find((e) => e.bookId === bookId && e.unit === u && same(e));
    if (hit) return hit;
  }
  if (bookId) {
    const hit = CPP_WORDBANK.find((e) => e.bookId === bookId && same(e));
    if (hit) return hit;
  }
  return CPP_WORDBANK.find(same) || null;
}
